import assert from "node:assert/strict";
import { default as __ns1_epsilon } from "./src/epsilon.js";
import { default as __ns1_sampleRankCorrelation } from "./src/sample_rank_correlation.js";
const ss = Object.freeze({ epsilon: __ns1_epsilon, sampleRankCorrelation: __ns1_sampleRankCorrelation });
{
{
{
// The same three paired observations {(1,1), (1,2), (2,1)}, with the
        // first two rows swapped. A correlation is a property of the pairs,
        // so both orderings must agree.
        const first = ss.sampleRankCorrelation([1, 1, 2], [1, 2, 1]);
        const second = ss.sampleRankCorrelation([1, 1, 2], [2, 1, 1]);
        assert.ok(Math.abs(first - second) < ss.epsilon, `orderings disagree: ${first} vs ${second}`);
}
}
}

