import assert from "node:assert/strict";
import { default as __ns1_epsilon } from "./src/epsilon.js";
import { default as __ns1_sampleRankCorrelation } from "./src/sample_rank_correlation.js";
const ss = Object.freeze({ epsilon: __ns1_epsilon, sampleRankCorrelation: __ns1_sampleRankCorrelation });
{
{
{
const x = Object.freeze([1, 1, 2, 2, 3, 3]);
        const y = Object.freeze([1, 2, 2, 3, 1, 3]);
        const expected = ss.sampleRankCorrelation(x, y);
        const orderings = [
            [5, 4, 3, 2, 1, 0],
            [1, 0, 3, 2, 5, 4],
            [2, 4, 0, 5, 1, 3],
            [3, 1, 4, 0, 2, 5]
        ];
        for (const order of orderings) {
            const rankCorr = ss.sampleRankCorrelation(order.map((i) => x[i]), order.map((i) => y[i]));
            assert.ok(Math.abs(rankCorr - expected) < ss.epsilon, `reordering changed the result: ${rankCorr} vs ${expected}`);
        }
}
}
}

